import { useEffect, useState } from 'react';
import client from '../api/client';
import { useAuth } from '../context/AuthContext';

export default function UsersPage() {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState([]);
  const [form, setForm] = useState({ email: '', password: '', fullName: '', role: 'USER' });
  const [status, setStatus] = useState('');
  const [passwordEditId, setPasswordEditId] = useState(null);
  const [passwordForm, setPasswordForm] = useState({ newPassword: '', confirmPassword: '' });
  const [passwordStatus, setPasswordStatus] = useState('');

  function load() {
    client.get('/users').then((r) => setUsers(r.data));
  }
  useEffect(load, []);

  async function createUser(e) {
    e.preventDefault();
    setStatus('');
    try {
      await client.post('/users', form);
      setForm({ email: '', password: '', fullName: '', role: 'USER' });
      setStatus('User created');
      load();
    } catch (err) {
      setStatus('Failed: ' + (err.response?.data || err.message));
    }
  }

  async function toggleEnabled(user) {
    await client.put(`/users/${user.id}`, { enabled: !user.enabled });
    load();
  }

  async function changeRole(user, role) {
    await client.put(`/users/${user.id}`, { role });
    load();
  }

  function startPasswordEdit(user) {
    setPasswordEditId(user.id);
    setPasswordForm({ newPassword: '', confirmPassword: '' });
    setPasswordStatus('');
  }

  function cancelPasswordEdit() {
    setPasswordEditId(null);
    setPasswordForm({ newPassword: '', confirmPassword: '' });
    setPasswordStatus('');
  }

  async function savePassword(e, user) {
    e.preventDefault();
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      setPasswordStatus('Passwords do not match');
      return;
    }
    if (passwordForm.newPassword.length < 8) {
      setPasswordStatus('Password must be at least 8 characters');
      return;
    }
    try {
      await client.put(`/users/${user.id}`, { newPassword: passwordForm.newPassword });
      cancelPasswordEdit();
    } catch (err) {
      setPasswordStatus('Failed: ' + (err.response?.data || err.message));
    }
  }

  return (
    <div style={{ padding: 24 }}>
      <h2>Users</h2>

      <form onSubmit={createUser} style={{ marginBottom: 24, fontSize: 13, display: 'flex', gap: 8, alignItems: 'end', flexWrap: 'wrap' }}>
        <label>Email<br />
          <input required type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
        </label>
        <label>Password<br />
          <input required type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
        </label>
        <label>Full name<br />
          <input value={form.fullName} onChange={(e) => setForm({ ...form, fullName: e.target.value })} />
        </label>
        <label>Role<br />
          <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
            <option value="USER">User</option>
            <option value="ADMIN">Admin</option>
            <option value="SUPER_USER">Super User</option>
          </select>
        </label>
        <button type="submit">Create user</button>
      </form>
      {status && <p style={{ fontSize: 13 }}>{status}</p>}

      <table style={{ borderCollapse: 'collapse', fontSize: 13 }}>
        <thead>
          <tr style={{ background: '#fafafa' }}>
            <th style={th}>Email</th><th style={th}>Name</th><th style={th}>Role</th><th style={th}>Enabled</th><th style={th}></th>
          </tr>
        </thead>
        <tbody>
          {users.map((u) => {
            const isSelf = currentUser?.email?.toLowerCase() === u.email?.toLowerCase();
            return (
              <tr key={u.id}>
                <td style={td}>{u.email}</td>
                <td style={td}>{u.fullName}</td>
                <td style={td}>
                  <select value={u.role} onChange={(e) => changeRole(u, e.target.value)}>
                    <option value="USER">User</option>
                    <option value="ADMIN">Admin</option>
                    <option value="SUPER_USER">Super User</option>
                  </select>
                </td>
                <td style={td}>{u.enabled ? 'Yes' : 'No'}</td>
                <td style={td}>
                  <button onClick={() => toggleEnabled(u)}>{u.enabled ? 'Disable' : 'Enable'}</button>
                  {passwordEditId !== u.id && (
                    <button style={{ marginLeft: 8 }} onClick={() => startPasswordEdit(u)}>
                      {isSelf ? 'Change Password' : 'Reset Password'}
                    </button>
                  )}
                  {passwordEditId === u.id && (
                    <form onSubmit={(e) => savePassword(e, u)} style={{ display: 'inline-flex', gap: 4, marginLeft: 8, alignItems: 'center' }}>
                      <input
                        required
                        type="password"
                        placeholder="New password"
                        value={passwordForm.newPassword}
                        onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                        style={{ width: 120 }}
                      />
                      <input
                        required
                        type="password"
                        placeholder="Confirm"
                        value={passwordForm.confirmPassword}
                        onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                        style={{ width: 100 }}
                      />
                      <button type="submit">Save</button>
                      <button type="button" onClick={cancelPasswordEdit}>Cancel</button>
                    </form>
                  )}
                  {passwordEditId === u.id && passwordStatus && (
                    <div style={{ color: '#d64545', fontSize: 12, marginTop: 4 }}>{passwordStatus}</div>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

const th = { textAlign: 'left', padding: '6px 10px', borderBottom: '1px solid #eee' };
const td = { padding: '6px 10px', borderBottom: '1px solid #eee' };
